def heads_for(cells, top, bot):
    out = []
    for h in cells["heads"]:
        # keep plausible heads only
        if not (18 <= h["w"] <= 42 and 14 <= h["h"] <= 40 and h["a"] >= 220):
            continue
        out.append(h)
    return out

def off_of(x, xa, xb):
    f = (x - xa) / max(1, xb - xa)
    e = int(round(f * 8))
    e = max(0, min(7, e))
    return {0: "0", 1: "1/8", 2: "1/4", 3: "3/8", 4: "1/2", 5: "5/8", 6: "3/4", 7: "7/8"}[e]

