for page in range(2, 13):
    cells = json.load(open(f"work/cells_p{page:02d}.json"))
    grid = GRIDS[page]
    notes = []
    barsout = {}
    for si, bars in enumerate(grid, 1):
        s = next((x for x in cells["systems"] if x["sys"] == si), None)
        if s is None:
            barsout[str(si)] = [{"xa": a, "xb": b, "label": l} for a, b, l in bars]
            continue
        barsout[str(si)] = [{"xa": a, "xb": b, "label": l.replace("II:", "").replace("III:", "").replace("IV:", "").replace("x", "")} for a, b, l in bars]
        hh = heads_for(s, s["top"], s["bot"])
        for a, b, lab in bars:
            if "–" in lab:
                continue  # rest block
            blab = lab.split(":")[-1].rstrip("x")
            if not blab:
                continue
            barn = int(blab)
            for h in hh:
                if a <= h["x"] < b:
                    p = pitch(h["k"])
                    # skip clef/key region and digits: heads only inside staff±ledger
                    if h["k"] < -3 or h["k"] > 16:
                        continue
                    notes.append({"sys": si, "x": h["x"], "y": round(s["bot"] - h["k"] * 12.75),
                                  "pitch": p, "clef": "bass", "bar": barn,
                                  "dur": "1/8", "off": off_of(h["x"], a, b),
                                  "tie_from_prev": False, "uncertain": UNC})
    mvts = []
    if page == 5:
        mvts = [{"mvt": "II", "starts_at": {"sys": 5, "x": 340}}]
    if page == 7:
        mvts = [{"mvt": "III", "starts_at": {"sys": 3, "x": 340}}]
    if page == 9:
        mvts = [{"mvt": "IV", "starts_at": {"sys": 6, "x": 340}}]
    allbars = [l.split(":")[-1].rstrip("x") for s in grid for a, b, l in s if "–" not in l]
    notes.sort(key=lambda n: (n["sys"], n["x"]))
    bars_meta = META_BARS.get(page, [allbars[0], allbars[-1]])
    json.dump({"page": page, "movements": mvts, "notes": notes,
               "meta": {"bars": bars_meta, "meters": [], "tempos": [],
                        "key_signatures": [], "repeats": REPEATS.get(page, ""),
                        "movement_last_bar": {}}},
              open(f"work/notes_p{page:02d}_draft.json", "w"), ensure_ascii=False, indent=1)
    json.dump(barsout, open(f"work/bars_p{page:02d}_draft.json", "w"), ensure_ascii=False, indent=1)
    print(f"p{page:02d}: {len(notes)} notes, bars {allbars[0]}-{allbars[-1]}")
